#include <algorithm>
#include <array>
#include <cassert>
#include <cstdint>
#include <fstream>
#include <iostream>
#include <set>
#include <vector>
using namespace std;
using U=__uint128_t;
const int LIM=24696;
vector<int> sm,pr;
vector<array<int,6>> pats;
int gb[8]={0,1,2,4,5,6,8,9};
void gen(int i,int n){static int ps[]={2,3,5,7};if(i==4){sm.push_back(n);return;}for(;;){gen(i+1,n);if(n>LIM/ps[i])break;n*=ps[i];}}
void patgen(int i,int left,array<int,6>&a){if(i==5){a[i]=left;int sp=a[1]+a[3]+a[4],sq=a[2]+a[4]+a[5];if(sp>=3&&sq>=3&&sp<7&&sq<7&&a[4]&&a[0]<=3)pats.push_back(a);return;}for(int t=0;t<=left;t++){a[i]=t;patgen(i+1,left-t,a);}}
int units(int M,int p,int D){for(int k=0;k<=D;k++){int sum=0;for(int v=p;v<=M;){sum+=min(k,M/v);if(v>M/p)break;v*=p;}if(sum>=D)return k;}return D+1;}
int forced_units(int M,int p,int D,int e){int worst=0;for(int v=e;v<=D;v++){if(v>=D)break;int req=D+1;for(int k=0;k<=D;k++){int sum=v,E=1;for(int w=p;w<=M;E++){sum+=min(k,max(0,M/w-(v>=E)));if(w>M/p)break;w*=p;}if(sum>=D){req=k;break;}}worst=max(worst,req);}return worst;}
bool scalar_pack(U Q,int M,int forbidden,int slots){if(Q==1)return true;if(slots<=0)return false;if(slots==1)return Q<=U(M/(forbidden+1));U threshold=U(-1);for(int p:{2,3,5,7}){if(p>M/(forbidden+slots))return false;U t=p;for(int j=1;j<=slots;j++)t*=max(M/((forbidden+j)*p)+1,p);threshold=min(threshold,t);}return Q<threshold;}
bool rough_pack(const array<U,4>&Q,int M,int forbidden,int slots){if(Q[0]==1)return true;if(slots<=0)return false;if(slots==1)return Q[0]<=U(M/(forbidden+1));int ps[]={2,3,5,7};for(int h=0;h<4;h++){int p=ps[h];if(p>M/(forbidden+slots))return false;U t=p;for(int j=1;j<=slots;j++)t*=max(M/((forbidden+j)*p)+1,p);if(Q[h]>=t)return false;}return true;}
int main(int argc,char**argv){gen(0,1);sort(sm.begin(),sm.end());for(int p=11;p<=1500;p++){bool ok=1;for(int d=2;d*d<=p;d++)if(p%d==0){ok=0;break;}if(ok)pr.push_back(p);}array<int,6>a{};patgen(0,7,a);cerr<<"patterns "<<pats.size()<<"\n";ofstream out(argc>1?argv[1]:"g7_exact/two/envelope_residual.txt");uint64_t pairs=0,configs=0,eligible=0,closed=0,resid=0;int maxM=0;array<uint64_t,4>zr{};for(int p:pr){if(p*p>LIM)break;int K=min(LIM,9*p*p-1);for(int q:pr){if(q<=p)continue;if(p*q>K)break;pairs++;array<int,6>core={1,p,q,p*p,p*q,q*q};set<int>maxima;for(int d:core)if(d<=K)for(int s:sm){if(s>K/d)break;int M=d*s;if(M>=p*q&&M>=3*q)maxima.insert(M);}for(int M:maxima){configs++;int mc=-1,ms=0;for(int h=0;h<6;h++)if(M%core[h]==0&&binary_search(sm.begin(),sm.end(),M/core[h])){assert(mc<0);mc=h;ms=M/core[h];}assert(mc>=0);array<vector<int>,6>top;for(int h=0;h<6;h++){auto it=upper_bound(sm.begin(),sm.end(),M/core[h]);while(it!=sm.begin()&&top[h].size()<7){--it;if(7LL*core[h]*(*it)<=M)break;if(core[h]*(*it)>=2)top[h].push_back(*it);}}U rp[6][2][4][8]{}; int available[6]{}; for(int h=1;h<6;h++){vector<int> vals;for(int s:sm){if(s>M/core[h])break;if(7LL*core[h]*s>M)vals.push_back(s);}available[h]=vals.size();for(int ex=0;ex<2;ex++)for(int threshold=0;threshold<4;threshold++){int ps[]={2,3,5,7};vector<int> rough;for(int j=0;j<int(vals.size())-ex;j++){int v=vals[j];for(int l=0;l<threshold;l++)while(v%ps[l]==0)v/=ps[l];rough.push_back(v);}sort(rough.rbegin(),rough.rend());rp[h][ex][threshold][0]=1;for(int t=1;t<=7;t++)rp[h][ex][threshold][t]=(t<=int(rough.size())?rp[h][ex][threshold][t-1]*rough[t-1]:U(-1));}}
for(auto c:pats){if(!c[mc])continue;bool ok=1;for(int h=0;h<6;h++)if(c[h]>int(top[h].size()))ok=0;if(!ok)continue;int sp=c[1]+c[3]+c[4],sq=c[2]+c[4]+c[5];if((sp==3&&!c[3]&&p*p<=M)||(sq==3&&!c[5]&&q*q<=M))continue;eligible++;int z=c[0],m=7-z,r=gb[z],Dp=c[1]+2*c[3]+c[4],Dq=c[2]+c[4]+2*c[5];U Q=1;for(int h=1;h<6;h++)for(int j=0;j<c[h];j++)Q*=top[h][j];int C=min(m,units(M,p,Dp)+units(M,q,Dq));bool done=scalar_pack(Q,M,r,9-r-C);static int ep[6]={0,1,0,2,1,0},eq[6]={0,0,1,0,1,2};if(!done)for(int h=1;h<6;h++)if(c[h]){int Cf=min(m,1+forced_units(M,p,Dp,ep[h])+forced_units(M,q,Dq,eq[h]));if(scalar_pack(Q/top[h][0],M,r+1,9-r-Cf)){done=1;break;}}if(!done)for(int anchor=1;anchor<6;anchor++)if(c[anchor]){int Cf=min(m,1+forced_units(M,p,Dp,ep[anchor])+forced_units(M,q,Dq,eq[anchor]));array<U,4> bounds{1,1,1,1};for(int threshold=0;threshold<4;threshold++)for(int h=1;h<6;h++)bounds[threshold]*=rp[h][h==anchor][threshold][c[h]-(h==anchor)];if(rough_pack(bounds,M,r+1,9-r-Cf)){done=1;break;}}if(done){closed++;continue;}resid++;zr[z]++;maxM=max(maxM,M);out<<p<<' '<<q<<' '<<M;for(int t:c)out<<' '<<t;out<<'\n';}}}cerr<<"p "<<p<<" configs "<<configs<<" eligible "<<eligible<<" closed "<<closed<<" residual "<<resid<<" maxM "<<maxM<<"\n";}cout<<"{\"pairs\":"<<pairs<<",\"configs\":"<<configs<<",\"eligible\":"<<eligible<<",\"closed\":"<<closed<<",\"residual\":"<<resid<<",\"maxM\":"<<maxM<<",\"z\":[";for(int i=0;i<4;i++)cout<<(i?",":"")<<zr[i];cout<<"]}\n";}
